package com.hazrob.tank.chemcore.v6;

import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;

/**
 * N05 evaluation harness for ORIGINAL verified UCI1081 exposures.
 * Features are generated by extract_uci1081_verified.py; this class must never
 * learn on any withheld exposure or use a legacy inference engine.
 *
 * Source-level holdout is by entire 50/100/200 ppb concentration groups.
 * The original source DOES NOT establish device/day independence, and the
 * source's MQ135 has not been validated as interchangeable with Tank MQ135.
 * Scores are research-only, not physical ppm or certified gas identity.
 */
public final class Uci1081JavaV6Benchmark {
    private static final String[] GASES={"ethanol","acetone","toluene",
        "ethyl acetate","isopropanol","hexane"};
    private static final int[] LEVELS={50,100,200};
    private static final String[] MODES={"MQ135_only","full_source_10_channels"};
    private static final String[] ALGORITHMS={
        "V6_DiagonalLDA","V6_KNN_k3","V6_Softmax","V6_PCA2_then_DiagonalLDA"
    };
    private static final class Record {
        final int id,ppb;
        final String gas;
        final double[] features;
        Record(int id,String gas,int ppb,double[] features){
            this.id=id;this.gas=gas;this.ppb=ppb;this.features=features;
        }
    }
    private static void require(boolean valid,String message){
        if(!valid)throw new IllegalArgumentException(message);
    }
    private static List<Record> load(Path csv) throws IOException {
        List<Record> out=new ArrayList<>();
        try(BufferedReader reader=Files.newBufferedReader(csv,StandardCharsets.UTF_8)){
            String header=reader.readLine();
            require(header!=null&&header.startsWith("row_id,gas,ppb,f00,"),
                "Expected source-defined 30-feature header");
            String line;
            while((line=reader.readLine())!=null){
                String[] v=line.split(",",-1);
                require(v.length==33,"33 source columns (id,gas,ppb,30 features)");
                int id=Integer.parseInt(v[0]),ppb=Integer.parseInt(v[2]);
                require(id==out.size(),"source row IDs must be complete and ordered");
                require(Arrays.asList(GASES).contains(v[1]),"unknown original gas");
                boolean validPpb=false;
                for(int k:LEVELS)if(k==ppb)validPpb=true;
                require(validPpb,"unknown original concentration");
                double[] features=new double[30];
                for(int i=0;i<30;i++){
                    features[i]=Double.parseDouble(v[i+3]);
                    require(Double.isFinite(features[i]),"nonfinite original source feature");
                }
                out.add(new Record(id,v[1],ppb,features));
            }
        }
        require(out.size()==90,"original source must have exactly 90 exposures");
        for(String gas:GASES)for(int ppb:LEVELS){
            int count=0;
            for(Record r:out)if(r.gas.equals(gas)&&r.ppb==ppb)count++;
            require(count==5,"original source replicates per gas/concentration");
        }
        return out;
    }
    private static double[] select(Record r,String mode){
        if(mode.equals("MQ135_only"))
            return new double[]{r.features[4],r.features[14],r.features[24]};
        return r.features.clone();
    }
    private static String first(List<ClassicalLearningV6.ClassScore> ranks){
        require(ranks!=null&&!ranks.isEmpty(),"empty source classification ranks");
        return ranks.get(0).label;
    }
    private static String[] predict(String model,double[][] trainX,String[] trainY,
                                    double[][] testX){
        var training=new ClassicalLearningV6.Dataset(trainX,trainY);
        require(training.validRows==60&&training.classes.size()==6,
                "train-only 60 source exposures and all six gas labels required");
        String[] predicted=new String[testX.length];
        switch(model){
            case "V6_DiagonalLDA": {
                var m=ClassicalLearningV6.fitDiagonalLDA(training,.05);
                for(int i=0;i<testX.length;i++)predicted[i]=first(m.score(testX[i]));
                break;
            }
            case "V6_KNN_k3": {
                var m=ClassicalLearningV6.fitKnn(training);
                for(int i=0;i<testX.length;i++)predicted[i]=first(m.rank(testX[i],3));
                break;
            }
            case "V6_Softmax": {
                var m=ClassicalLearningV6.fitSoftmax(training,800,.15,.005);
                for(int i=0;i<testX.length;i++)predicted[i]=first(m.scores(testX[i]));
                break;
            }
            case "V6_PCA2_then_DiagonalLDA": {
                // Fit source scale and PCA on TRAIN only; project test without fitting.
                var std=ClassicalLearningV6.Standardizer.fit(trainX);
                double[][] fitZ=new double[trainX.length][];
                for(int i=0;i<fitZ.length;i++)fitZ[i]=std.transform(trainX[i]);
                var pca=ClassicalLearningV6.pca(fitZ,2);
                double[][] projX=new double[trainX.length][];
                for(int i=0;i<fitZ.length;i++)projX[i]=pca.transform(fitZ[i]);
                var m=ClassicalLearningV6.fitDiagonalLDA(
                    new ClassicalLearningV6.Dataset(projX,trainY),.05);
                for(int i=0;i<testX.length;i++)
                    predicted[i]=first(m.score(pca.transform(std.transform(testX[i]))));
                break;
            }
            default:throw new IllegalArgumentException("unregistered V6 algorithm");
        }
        return predicted;
    }
    private static void run(Path input,Path predFile,Path metricsFile)throws IOException {
        List<Record> records=load(input);
        try(BufferedWriter predictions=Files.newBufferedWriter(predFile,StandardCharsets.UTF_8);
            BufferedWriter metrics=Files.newBufferedWriter(metricsFile,StandardCharsets.UTF_8)){
            predictions.write("mode,algorithm,heldout_ppb,source_row_id,actual,predicted\n");
            metrics.write("mode,algorithm,heldout_ppb,training_exposures,test_exposures,accuracy,balanced_accuracy,macro_f1\n");
            for(String mode:MODES){
                for(int level:LEVELS){
                    List<Record> training=new ArrayList<>(),test=new ArrayList<>();
                    for(Record r:records)(r.ppb==level?test:training).add(r);
                    require(training.size()==60&&test.size()==30,
                        "whole-level 60/30 original exposures");
                    double[][] trainX=new double[60][],testX=new double[30][];
                    String[] trainY=new String[60],testY=new String[30];
                    for(int i=0;i<60;i++){
                        trainX[i]=select(training.get(i),mode);
                        trainY[i]=training.get(i).gas;
                    }
                    for(int i=0;i<30;i++){
                        testX[i]=select(test.get(i),mode);
                        testY[i]=test.get(i).gas;
                    }
                    for(String algorithm:ALGORITHMS){
                        String[] predicted=predict(algorithm,trainX,trainY,testX);
                        var score=SourceValidationV6.benchmark(testY,predicted,GASES);
                        require(score.evaluated==30,"all 30 held-out source exposures scored");
                        String line=String.format(Locale.ROOT,
                            "%s,%s,%d,60,30,%.10f,%.10f,%.10f%n",
                            mode,algorithm,level,score.accuracy,
                            score.balancedAccuracy,score.macroF1);
                        metrics.write(line);
                        System.out.print("N05_SOURCE_ONLY "+line);
                        for(int i=0;i<30;i++)
                            predictions.write(mode+","+algorithm+","+level+","+
                                test.get(i).id+","+testY[i]+","+predicted[i]+"\n");
                    }
                }
            }
        }
    }
    public static void main(String[] args)throws Exception {
        require(args.length==3,
            "Usage Uci1081JavaV6Benchmark verified_features.csv predictions.csv metrics.csv");
        run(Path.of(args[0]),Path.of(args[1]),Path.of(args[2]));
        System.out.println("PASS N05: 90 ORIGINAL source exposures; 3 sealed concentration folds;");
        System.out.println("4 distinct new V6 Java algorithms x 2 channel modes;");
        System.out.println("No Tank device/day independence, ppm, or G3 certification.");
    }
}
